21	struct L1ICache_tb : Sysc_tb {
22	  sc_out<bool> io_flush_valid;
23	  sc_out<sc_bv<32> > io_flush_pcNext;
24	  sc_in<bool> io_flush_ready;
25	  sc_out<bool> io_ibus_valid;
26	  sc_in<bool> io_ibus_ready;
27	  sc_out<sc_bv<32> > io_ibus_addr;
28	  sc_in<sc_bv<kL1IAxiBits> > io_ibus_rdata;
29	  sc_in<bool> io_ibus_fault_valid;
30	  sc_in<bool> io_ibus_fault_bits_write;
31	  sc_in<sc_bv<32>> io_ibus_fault_bits_addr;
32	  sc_in<sc_bv<32>> io_ibus_fault_bits_epc;
33	  sc_in<bool> io_axi_read_addr_valid;
34	  sc_out<bool> io_axi_read_addr_ready;
35	  sc_in<sc_bv<kL1IAxiId> > io_axi_read_addr_bits_id;
36	  sc_in<sc_bv<32> > io_axi_read_addr_bits_addr;
37	  sc_in<sc_bv<4> > io_axi_read_addr_bits_region;
38	  sc_in<sc_bv<4> > io_axi_read_addr_bits_qos;
39	  sc_in<sc_bv<3> > io_axi_read_addr_bits_prot;
40	  sc_in<sc_bv<4> > io_axi_read_addr_bits_cache;
41	  sc_in<bool> io_axi_read_addr_bits_lock;
42	  sc_in<sc_bv<2> > io_axi_read_addr_bits_burst;
43	  sc_in<sc_bv<3> > io_axi_read_addr_bits_size;
44	  sc_in<sc_bv<8> > io_axi_read_addr_bits_len;
45	  sc_out<bool> io_axi_read_data_valid;
46	  sc_in<bool> io_axi_read_data_ready;
47	  sc_out<sc_bv<2> > io_axi_read_data_bits_resp;
48	  sc_out<sc_bv<kL1IAxiId> > io_axi_read_data_bits_id;
49	  sc_out<sc_bv<kL1IAxiBits> > io_axi_read_data_bits_data;
50	  sc_out<bool> io_axi_read_data_bits_last;
51	  sc_in<bool> io_volt_sel;
52	
53	  using Sysc_tb::Sysc_tb;
54	
55	  void posedge() {
56	    // flush
57	    io_flush_valid = rand_int(0, 255) == 0;
58	
59	    // ibus
60	    if (ibus_resp_pipeline_) {
61	      ibus_resp_pipeline_ = false;
62	      for (int i = 0; i < ibusw_; ++i) {
63	        uint32_t ref = ibus_resp_data_ + i * 4;
64	        uint32_t dut = io_ibus_rdata.read().get_word(i);
65	        check(ref == dut, "ibus read data");
66	      }
67	    }
68	
69	    if (io_ibus_valid && io_ibus_ready) {
70	      ibus_resp_pipeline_ = true;
71	      ibus_resp_data_ = io_ibus_addr.read().get_word(0) & ~(ibusb_ - 1);
72	
73	      command_t cmd({io_ibus_addr.read().get_word(0)});
74	      history_.write(cmd);
75	      if (history_.count() > 16) {
76	        history_.remove();
77	      }
78	    }
79	
80	    if (!io_ibus_valid || io_ibus_ready) {  // latch transaction
81	      command_t cmd;
82	      bool newaddr = rand_int(0, 3) == 0 || !history_.rand(cmd);
83	      uint32_t addr = newaddr ? rand_uint32() : cmd.addr;
84	      if (rand_int(0, 7) == 0) {
85	        addr &= 0x3fff;
86	      }
87	      io_ibus_valid = rand_bool();
88	      io_ibus_addr = addr;
89	    }
90	
91	    timeout_ = io_ibus_ready ? 0 : timeout_ + io_ibus_valid;
92	    check(timeout_ < 100, "ibus timeout");
93	
94	    // kxi_read_addr
95	    io_axi_read_addr_ready = rand_bool();
96	
97	    if (io_axi_read_addr_valid && io_axi_read_addr_ready) {
98	      uint32_t id = io_axi_read_addr_bits_id.read().get_word(0);
99	      uint32_t addr = io_axi_read_addr_bits_addr.read().get_word(0);
100	      response_t resp({id, addr});
101	      resp_.write(resp);
102	    }
103	
104	    // kxi_read_data
105	    io_axi_read_data_valid = false;
106	    io_axi_read_data_bits_id = 0;
107	    io_axi_read_data_bits_data = 0;
108	
109	    if (io_axi_read_data_valid && io_axi_read_data_ready) {
110	      check(resp_.remove(), "no response to erase");
111	      resp_.shuffle();
112	    }
113	
114	    response_t resp;
115	    if (resp_.next(resp)) {
116	      io_axi_read_data_valid = rand_bool();
117	      io_axi_read_data_bits_id = resp.id;
118	      uint32_t data = resp.data;
119	      sc_bv<kL1IAxiBits> out;
120	      for (int i = 0; i < axiw_; ++i) {
121	        out.set_word(i, data);
122	        data += 4;
123	      }
124	      io_axi_read_data_bits_data = out;
125	    }
126	  }
127	
128	 private:
129	  struct command_t {
130	    uint32_t addr;
131	  };
132	
133	  struct response_t {
134	    uint32_t id;
135	    uint32_t data;
136	  };
137	
138	  const int ibusb_ = kL1IAxiBits / 8;
139	  const int ibusw_ = kL1IAxiBits / 32;
140	  const int axib_ = kL1IAxiBits / 8;
141	  const int axiw_ = kL1IAxiBits / 32;
142	
143	  int timeout_ = 0;
144	
145	  bool ibus_resp_pipeline_ = false;
146	  uint32_t ibus_resp_data_ = 0;
147	  fifo_t<command_t> history_;
148	  fifo_t<response_t> resp_;
149	};
