212	  BIND2(tb, l1icache, io_axi_read_addr_bits_burst);
213	  BIND2(tb, l1icache, io_axi_read_addr_bits_size);
214	  BIND2(tb, l1icache, io_axi_read_addr_bits_len);
215	  BIND2(tb, l1icache, io_axi_read_data_ready);
216	  BIND2(tb, l1icache, io_axi_read_data_valid);
217	  BIND2(tb, l1icache, io_axi_read_data_bits_data);
