17	#ifndef L1DCACHEBANK
18	#include "VL1DCache.h"
19	constexpr int kDBusBankAdj = 0;
20	#else
21	#include "VL1DCacheBank.h"
22	constexpr int kDBusBankAdj = 1;
23	#endif
24	
25	#include "tests/verilator_sim/coralnpu/coralnpu_cfg.h"
26	
27	constexpr int kLineSize = kVector / 8;
28	constexpr int kLineBase = ~(kLineSize - 1);
29	constexpr int kLineOffset = kLineSize - 1;
30	constexpr int kVLenB = kVector / 8;
31	constexpr int kVLenW = kVLenB / sizeof(int32_t);
32	
33	struct L1DCache_tb : Sysc_tb {
34	  sc_out<bool> io_flush_valid;
35	  sc_in<bool> io_flush_ready;
36	  sc_out<bool> io_flush_all;
37	  sc_out<bool> io_flush_clean;
38	
39	  sc_out<bool> io_dbus_valid;
40	  sc_in<bool> io_dbus_ready;
41	  sc_out<bool> io_dbus_write;
42	  sc_out<sc_bv<kDbusBits> > io_dbus_size;
43	  sc_out<sc_bv<32 - kDBusBankAdj> > io_dbus_addr;
44	  sc_out<sc_bv<32 - kDBusBankAdj> > io_dbus_adrx;
45	  sc_in<sc_bv<kVector> > io_dbus_rdata;
46	  sc_in<sc_bv<32> > io_dbus_pc;
47	  sc_out<sc_bv<kVector> > io_dbus_wdata;
48	  sc_out<sc_bv<kVector / 8> > io_dbus_wmask;
49	
50	  sc_in<bool> io_axi_read_addr_valid;
51	  sc_out<bool> io_axi_read_addr_ready;
52	  sc_in<sc_bv<kL1DAxiId - kDBusBankAdj> > io_axi_read_addr_bits_id;
53	  sc_in<sc_bv<32 - kDBusBankAdj> > io_axi_read_addr_bits_addr;
54	  sc_in<sc_bv<4> > io_axi_read_addr_bits_region;
55	  sc_in<sc_bv<4> > io_axi_read_addr_bits_qos;
56	  sc_in<sc_bv<3> > io_axi_read_addr_bits_prot;
57	  sc_in<sc_bv<4> > io_axi_read_addr_bits_cache;
58	  sc_in<bool> io_axi_read_addr_bits_lock;
59	  sc_in<sc_bv<2> > io_axi_read_addr_bits_burst;
60	  sc_in<sc_bv<3> > io_axi_read_addr_bits_size;
61	  sc_in<sc_bv<8> > io_axi_read_addr_bits_len;
62	
63	  sc_out<bool> io_axi_read_data_valid;
64	  sc_in<bool> io_axi_read_data_ready;
65	  sc_out<sc_bv<2> > io_axi_read_data_bits_resp;
66	  sc_out<sc_bv<kL1DAxiId - kDBusBankAdj> > io_axi_read_data_bits_id;
67	  sc_out<sc_bv<kL1DAxiBits> > io_axi_read_data_bits_data;
68	  sc_out<bool> io_axi_read_data_bits_last;
69	
70	  sc_in<bool> io_axi_write_addr_valid;
71	  sc_out<bool> io_axi_write_addr_ready;
72	  sc_in<sc_bv<kL1DAxiId - kDBusBankAdj> > io_axi_write_addr_bits_id;
73	  sc_in<sc_bv<32 - kDBusBankAdj> > io_axi_write_addr_bits_addr;
74	  sc_in<sc_bv<4> > io_axi_write_addr_bits_region;
75	  sc_in<sc_bv<4> > io_axi_write_addr_bits_qos;
76	  sc_in<sc_bv<3> > io_axi_write_addr_bits_prot;
77	  sc_in<sc_bv<4> > io_axi_write_addr_bits_cache;
78	  sc_in<bool> io_axi_write_addr_bits_lock;
79	  sc_in<sc_bv<2> > io_axi_write_addr_bits_burst;
80	  sc_in<sc_bv<3> > io_axi_write_addr_bits_size;
81	  sc_in<sc_bv<8> > io_axi_write_addr_bits_len;
82	
83	  sc_in<bool> io_axi_write_data_valid;
84	  sc_out<bool> io_axi_write_data_ready;
85	  sc_in<sc_bv<kL1DAxiStrb> > io_axi_write_data_bits_strb;
86	  sc_in<sc_bv<kL1DAxiBits> > io_axi_write_data_bits_data;
87	  sc_in<bool> io_axi_write_data_bits_last;
88	
89	  sc_out<bool> io_axi_write_resp_valid;
90	  sc_in<bool> io_axi_write_resp_ready;
91	  sc_out<sc_bv<2> > io_axi_write_resp_bits_resp;
92	  sc_out<sc_bv<kL1DAxiId - kDBusBankAdj> > io_axi_write_resp_bits_id;
93	
94	  sc_in<bool> io_volt_sel;
95	
96	  using Sysc_tb::Sysc_tb;
97	
98	  void posedge() {
99	    // dbus
100	#ifdef L1DCACHEBANK
101	    // Checks a bank cache line.
102	    if (dbus_resp_pipeline_) {
103	      dbus_resp_pipeline_ = false;
104	      uint32_t addr = dbus_resp_addr_;
105	      uint32_t size = dbus_resp_size_;
106	      for (uint32_t i = 0; i < kVLenB && size; ++i) {
107	        uint8_t ref = dbus_resp_data_[i];
108	        uint8_t dut = io_dbus_rdata.read().get_word(i / 4) >> (8 * i);
109	        if (ref != dut) {
110	          printf("DDD(%u) %08x : %02x %02x\n", i, (addr & ~(kVLenB - 1)) + i,
111	                 ref, dut);
112	        }
113	        check(ref == dut, "dbus read data");
114	      }
115	    }
116	#else
117	    if (dbus_resp_pipeline_) {
118	      dbus_resp_pipeline_ = false;
119	      uint32_t addr = dbus_resp_addr_;
120	      uint32_t size = dbus_resp_size_;
121	      for (uint32_t j = addr; j < addr + size; ++j) {
122	        uint32_t i = j & (kVLenB - 1);
123	        uint8_t ref = dbus_resp_data_[i];
124	        uint8_t dut = io_dbus_rdata.read().get_word(i / 4) >> (8 * i);
125	        check(ref == dut, "dbus read data");
126	      }
127	    }
128	#endif
129	
130	    if (io_dbus_valid && io_dbus_ready && !io_dbus_write) {
131	      dbus_active_ = false;
132	      dbus_resp_pipeline_ = true;
133	      dbus_resp_addr_ = io_dbus_addr.read().get_word(0);
134	      dbus_resp_size_ = io_dbus_size.read().get_word(0);
135	#ifdef L1DCACHEBANK
136	      ReadBus(dbus_resp_addr_ & kLineBase, kVLenB, dbus_resp_data_);
137	#else
138	      ReadBus(dbus_resp_addr_, kVLenB, dbus_resp_data_);
139	#endif
140	      history_t cmd({dbus_resp_addr_});
141	      history_.write(cmd);
142	      if (history_.count() > 16) {
143	        history_.remove();
144	      }
145	    }
146	
147	    if (io_dbus_valid && io_dbus_ready && io_dbus_write) {
148	      dbus_active_ = false;
149	
150	      uint32_t addr = io_dbus_addr.read().get_word(0);
151	      int size = io_dbus_size.read().get_word(0);
152	      uint8_t wdata[kVLenB];
153	      uint32_t* p_wdata = reinterpret_cast<uint32_t*>(wdata);
154	      for (int i = 0; i < kVLenW; ++i) {
155	        p_wdata[i] = io_dbus_wdata.read().get_word(i);
156	      }
157	      const uint32_t linemask = kVLenB - 1;
158	#ifdef L1DCACHEBANK
159	      const uint32_t linebase = addr & ~linemask;
160	#endif
161	      for (int i = 0; i < size; ++i, ++addr) {
162	        const uint32_t lineoffset = addr & linemask;
163	        if (io_dbus_wmask.read().get_bit(lineoffset)) {
164	#ifdef L1DCACHEBANK
165	          WriteBus(linebase + lineoffset, wdata[lineoffset]);
166	#else
167	          WriteBus(addr, wdata[lineoffset]);
168	#endif
169	        }
170	      }
171	    }
172	
173	    if (io_flush_valid && io_flush_ready) {
174	      flush_valid_ = false;
175	      flush_all_ = false;
176	      flush_clean_ = false;
177	    }
178	
179	    if (++flush_count_ > 5000 && !dbus_active_ && !flush_valid_) {
180	      // Flush controls must not change during handshake.
181	      flush_count_ = 0;
182	      flush_valid_ = true;
183	      flush_all_ = rand_bool();
184	      flush_clean_ = rand_bool();
185	    }
186	
187	    io_flush_valid = flush_valid_;
188	    io_flush_all = flush_all_;
189	    io_flush_clean = flush_clean_;
190	
191	    history_t dbus;
192	    if (!io_dbus_valid || !dbus_active_) {  // latch transaction
193	      bool valid = rand_bool() && !flush_valid_;
194	      bool write = rand_int(0, 3) == 0;
195	      bool newaddr = rand_int(0, 3) == 0 || !history_.rand(dbus);
196	      uint32_t addr =
197	          newaddr ? rand_uint32() : (dbus.addr + rand_int(-kVLenB, kVLenB));
198	      // TODO(b/295973540): avoids a raxi() crash.
199	      addr = std::min(0xffffff00u, addr);
200	      if (kDBusBankAdj) {
201	        addr &= 0x7fffffff;
202	      }
203	      if (rand_int(0, 7) == 0) {
204	        addr &= 0x3fff;
205	      }
206	#ifdef L1DCACHEBANK
207	      int size = rand_int(1, kVLenB);
208	#else
209	      int size = rand_int(0, kVLenB);
210	#endif
211	      io_dbus_valid = valid;
212	      io_dbus_write = write;
213	      io_dbus_addr = addr;
214	      io_dbus_adrx = addr + kVLenB;
215	      io_dbus_size = size;
216	      if (valid) {
217	        dbus_active_ = true;
218	        CheckAddr(addr, size);
219	      }
220	
221	      sc_bv<kVector> wdata = 0;
222	      sc_bv<kVector / 8> wmask = 0;
223	
224	      if (write) {
225	        for (int i = 0; i < kVLenW; ++i) {
226	          wdata.set_word(i, rand_uint32());
227	        }
228	        const uint32_t linemask = kVLenB - 1;
229	        const uint32_t lineoffset = addr & linemask;
230	        const bool all = rand_bool();
231	        for (int i = 0; i < size; ++i) {
232	          if (all || rand_bool()) {
233	            wmask.set_bit((i + lineoffset) & linemask, sc_dt::Log_1);
234	          }
235	        }
236	      }
237	
238	      io_dbus_wdata.write(wdata);
239	      io_dbus_wmask.write(wmask);
240	    }
241	
242	    timeout_ = io_dbus_ready ? 0 : timeout_ + io_dbus_valid;
243	    check(timeout_ < 10000, "dbus timeout");
244	
245	    // axi_read_addr
246	    io_axi_read_addr_ready = rand_bool();
247	
248	    if (io_axi_read_addr_valid && io_axi_read_addr_ready) {
249	      uint32_t id = io_axi_read_addr_bits_id.read().get_word(0);
250	      uint32_t addr = io_axi_read_addr_bits_addr.read().get_word(0);
251	      response_t resp({id, addr});
252	      resp_.write(resp);
253	    }
254	
255	    // axi_read_data
256	    io_axi_read_data_valid = false;
257	    io_axi_read_data_bits_id = 0;
258	    io_axi_read_data_bits_data = 0;
259	
260	    if (io_axi_read_data_valid && io_axi_read_data_ready) {
261	      check(resp_.remove(), "no response to erase");
262	    }
263	
264	    response_t resp;
265	    resp_.shuffle();
266	    if (resp_.next(resp)) {
267	      io_axi_read_data_valid = rand_bool();
268	      io_axi_read_data_bits_id = resp.id;
269	      uint32_t addr = resp.addr;
270	      sc_bv<kL1DAxiBits> out;
271	      for (int i = 0; i < axiw_; ++i) {
272	        uint32_t data;
273	        ReadAxi(addr, 4, reinterpret_cast<uint8_t*>(&data));
274	        out.set_word(i, data);
275	        addr += 4;
276	      }
277	      io_axi_read_data_bits_data = out;
278	    }
279	
280	    // axi_write_addr
281	    bool writedataready = rand_bool();
282	
283	    io_axi_write_addr_ready = writedataready;
284	
285	    if (io_axi_write_addr_valid && io_axi_write_addr_ready) {
286	      axiwaddr_t p;
287	      p.id = io_axi_write_addr_bits_id.read().get_word(0);
288	      p.addr = io_axi_write_addr_bits_addr.read().get_word(0);
289	      waddr_.write(p);
290	    }
291	
292	    // axi_write_data
293	    io_axi_write_data_ready = writedataready;
294	
295	    if (io_axi_write_data_valid && io_axi_write_data_ready) {
296	      axiwdata_t p;
297	      uint32_t* ptr = reinterpret_cast<uint32_t*>(p.data);
298	      for (int i = 0; i < axiw_; ++i, ++ptr) {
299	        ptr[0] = io_axi_write_data_bits_data.read().get_word(i);
300	      }
301	      for (int i = 0; i < axib_; ++i) {
302	        p.mask[i] = io_axi_write_data_bits_strb.read().get_bit(i);
303	      }
304	      wdata_.write(p);
305	    }
306	
307	    // axi_write_resp
308	    if (io_axi_write_resp_valid && io_axi_write_resp_ready) {
309	      wresp_.remove();
310	    }
311	
312	    axiwaddr_t wr;
313	    io_axi_write_resp_valid = rand_int(0, 4) == 0 && wresp_.next(wr);
314	    io_axi_write_resp_bits_id = wr.id;
315	
316	    // Process axi data write, and populate response.
317	    axiwaddr_t wa;
318	    axiwdata_t wd;
319	    if (waddr_.next(wa) && wdata_.next(wd)) {
320	      waddr_.remove();
321	      wdata_.remove();
322	      wresp_.write(wa);
323	
324	      uint32_t addr = wa.addr;
325	      for (int i = 0; i < axib_; ++i, ++addr) {
326	        if (wd.mask[i]) {
327	          WriteAxi(addr, wd.data[i]);
328	        }
329	      }
330	    }
331	  }
