394	  template <int outsz>
395	  void _Read(uint32_t addr, uint8_t size, uint8_t* data,
396	             std::map<uint32_t, uint8_t[kLineSize]>& m) {
397	    const uint32_t laddr = addr & kLineBase;
398	    const uint32_t loffset = addr & kLineOffset;
399	    const uint32_t doffset = addr & (outsz - 1);
400	#ifndef L1DCACHEBANK
401	    uint32_t start = addr;
402	    uint32_t end = std::min(addr + size, laddr + kLineSize);
403	    int size0 = end - start;
404	    int size1 = size - size0;
405	#endif
406	
407	    memset(data, 0xCC, outsz);
408	#ifdef L1DCACHEBANK
409	    assert(doffset == 0);
410	    memcpy(data + doffset, m[laddr] + loffset, outsz);
411	#else
412	    memcpy(data + doffset, m[laddr] + loffset, size0);
413	    if (!size1) return;
414	    memcpy(data, m[laddr + kLineSize], size1);
415	#endif
416	  }
417	
418	  void _Write(uint32_t addr, uint8_t data,
419	              std::map<uint32_t, uint8_t[kLineSize]>& m) {
420	    const uint32_t laddr = addr & kLineBase;
421	    const uint32_t loffset = addr & kLineOffset;
422	
423	    m[laddr][loffset] = data;
424	  }
425	
426	  void ReadBus(uint32_t addr, uint8_t size, uint8_t* data) {
427	    _Read<kVector / 8>(addr, size, data, mem_bus_);
428	  }
429	
430	  void ReadAxi(uint32_t addr, uint8_t size, uint8_t* data) {
431	    _Read<4>(addr, size, data, mem_axi_);
432	  }
433	
434	  void WriteBus(uint32_t addr, uint8_t data) { _Write(addr, data, mem_bus_); }
435	
436	  void WriteAxi(uint32_t addr, uint8_t data) { _Write(addr, data, mem_axi_); }
437	};
